(function(){'use strict';
const header=document.getElementById('siteHeader'),art=document.getElementById('heroArt'),toggle=document.getElementById('menuToggle'),mobile=document.getElementById('mobileNav'),reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
function onScroll(){const y=window.scrollY||0;header.classList.toggle('compact',y>40);if(!art||reduced)return;const heroHeight=Math.max(window.innerHeight,1);const progress=Math.min(Math.max(y/(heroHeight*.72),0),1);const scale=1-progress*.12;const move=progress*42;const opacity=1-progress*.92;const blur=progress*3;art.style.transform='translate(-50%,-50%) translateY('+move+'px) scale('+scale+')';art.style.opacity=String(opacity);art.style.filter='blur('+blur+'px) drop-shadow(0 42px 34px rgba(17,24,39,.16))';}
function closeMenu(){mobile.classList.remove('open');document.body.classList.remove('menu-open');toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Menyuni ochish');}
toggle&&toggle.addEventListener('click',()=>{const open=!mobile.classList.contains('open');mobile.classList.toggle('open',open);document.body.classList.toggle('menu-open',open);toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Menyuni yopish':'Menyuni ochish');});
